class SecurityToken {
    public boolean validateToken(String token) {
        System.out.println("Validating String token in parent: " + token);
        return token != null && token.length() > 5;
    }
}

class AdvancedSecurityToken extends SecurityToken {
    // ACCIDENTAL OVERLOAD (Without @Override):
    // Parameter is CharSequence, not String! This overloads instead of overrides!
    public boolean validateToken(CharSequence token) {
        System.out.println("Advanced validation");
        return true;
    }

    // CORRECT OVERRIDE (Protected by @Override):
    @Override
    public boolean validateToken(String token) {
        System.out.println("AdvancedSecurityToken validating exact String: " + token);
        return token != null && token.startsWith("SEC-");
    }
}

public class OverrideAnnotationDemo {
    public static void main(String[] args) {
        SecurityToken token = new AdvancedSecurityToken();
        // Dispatches to the correctly overridden method
        token.validateToken("SEC-9988");
    }
}

