class Account {
    protected String accountId;
    protected double balance;

    public Account(String id, double balance) {
        this.accountId = id;
        this.balance = balance;
    }

    public String formatSummary() {
        return "Account " + accountId + " Balance: $" + balance;
    }
}

class PremiumAccount extends Account {
    private String tier;

    public PremiumAccount(String id, double balance, String tier) {
        super(id, balance);
        this.tier = tier;
    }

    @Override
    public String formatSummary() {
        return "Premium Account " + accountId + " [" + tier + "] Balance: $" + balance;
    }
}

public class Main {
    public static void main(String[] args) {
        Account a1 = new Account("ACC-10", 500.0);
        Account a2 = new PremiumAccount("ACC-20", 25000.0, "Platinum");
        System.out.println("Standard: " + a1.formatSummary());
        System.out.println("Premium: " + a2.formatSummary());
    }
}

