class Calculator {
    public double add(double a, double b) {
        return a + b;
    }
}

class PrecisionCalculator extends Calculator {
    @Override
    public double add(double a, double b) {
        return Math.round((a + b) * 100.0) / 100.0;
    }
}

public class Main {
    public static void main(String[] args) {
        Calculator calc = new PrecisionCalculator();
        System.out.println("Precision Sum: " + calc.add(3.333, 4.444));
    }
}

class PipelineTask {
    public void executeTask() {
        System.out.println("PIPELINE TASK: Generic task execution");
    }
}

class SecurityAuditTask extends PipelineTask {
    @Override
    public void executeTask() {
        System.out.println("PIPELINE TASK: Scanning vulnerabilities... Zero threats found.");
    }
}

class DataTransformTask extends PipelineTask {
    @Override
    public void executeTask() {
        System.out.println("PIPELINE TASK: Transforming CSV records into compressed Parquet format.");
    }
}

public class Main {
    public static void main(String[] args) {
        PipelineTask[] tasks = new PipelineTask[] {
            new SecurityAuditTask(),
            new DataTransformTask()
        };
        for (PipelineTask t : tasks) {
            t.executeTask();
        }
    }
}
